# ---------------------------------------------------------------------------
# SVG: the labelled, colored, highlighted Cayley table
# ---------------------------------------------------------------------------
#
# One color per element, so structure is visible before any name is read: a
# constant row is one stripe, an identity row reproduces the header's colors,
# a group's table is a Latin square (every color once per row and column).

def u:palette(i) {
  unwrap(list_get(
    ["#7aa2f7", "#f7768e", "#9ece6a", "#e0af68", "#bb9af7",
     "#7dcfff", "#ff9e64", "#73daca"], mod(i, 8)))
}

def u:cell_px() { 64 }
def u:pad_px() { 44 }
def u:top_px() { 34 }

# One cell: a colored square plus the name of the product.
def u:cell_svg(names, t, n, a, b) {
  v = take(take(t, 0, a), 0, b)
  x = u:pad_px() + b * u:cell_px()
  y = u:top_px() + u:pad_px() + a * u:cell_px()
  inside = (1 - lt(v, 0)) * lt(v, n)
  fill = if inside { u:palette(v) } else { "#4a4a5a" }
  label = if inside { unwrap(list_get(names, v)) } else { u:cat("!", u:num(v)) }
  u:cat(
    u:svg_rect(x + 2, y + 2, u:cell_px() - 4, u:cell_px() - 4, fill),
    u:svg_text(x + u:cell_px() / 2, y + u:cell_px() / 2, "#11121a", label))
}

# Recursive fold over the n*n cells: sw-MLPL has no string reduction, so the
# accumulator is threaded by hand.  Recursion, not an explicit loop.
def u:cells_svg(names, t, n, i, acc) {
  if lt(i, n * n) {
    u:cells_svg(names, t, n, i + 1,
      u:cat(acc, u:cell_svg(names, t, n, floor(i / n), mod(i, n))))
  } else { acc }
}

# Row and column headings, same recursion.
def u:headers_svg(names, n, i, acc) {
  if lt(i, n) {
    col = u:svg_text(u:pad_px() + i * u:cell_px() + u:cell_px() / 2,
      u:top_px() + u:pad_px() - 14, "#c0caf5", unwrap(list_get(names, i)))
    row = u:svg_text(u:pad_px() / 2,
      u:top_px() + u:pad_px() + i * u:cell_px() + u:cell_px() / 2,
      "#c0caf5", unwrap(list_get(names, i)))
    u:headers_svg(names, n, i + 1, u:cat3(acc, col, row))
  } else { acc }
}

# A ring around the identity's row and column, when one exists.
def u:identity_svg(t) {
  n = u:order(t)
  e = u:identity_of(t)
  if u:has_identity(t) {
    u:cat(
      u:svg_frame(u:pad_px(), u:top_px() + u:pad_px() + e * u:cell_px(),
        n * u:cell_px(), u:cell_px()),
      u:svg_frame(u:pad_px() + e * u:cell_px(), u:top_px() + u:pad_px(),
        u:cell_px(), n * u:cell_px()))
  } else { "" }
}

def u:svg_frame(x, y, w, h) {
  u:cat5(u:cat5("<rect x=\"", u:num(x), "\" y=\"", u:num(y), "\" width=\""),
    u:num(w), "\" height=\"", u:num(h),
    "\" fill=\"none\" stroke=\"#ffffff\" stroke-width=\"3\"/>")
}

# The whole diagram: title, headings, colored cells, identity highlight.
def u:cayley_svg(title, names, t) {
  n = u:order(t)
  w = u:pad_px() + n * u:cell_px() + 16
  h = u:top_px() + u:pad_px() + n * u:cell_px() + 16
  u:cat3(
    u:cat3(u:svg_open(w, h), u:svg_rect(0, 0, w, h, "#1a1b26"),
      u:svg_text(w / 2, 18, "#c0caf5", title)),
    u:cat(u:headers_svg(names, n, 0, ""), u:cells_svg(names, t, n, 0, "")),
    u:cat(u:identity_svg(t), "</svg>"))
}

# Render and write in one call; returns the Result from write_text.
def u:write_cayley_svg(path, title, names, t) {
  write_text(path, u:cayley_svg(title, names, t))
}

